import * as z from "zod";

const UserId = z.string().brand<"UserId">();
const ReadonlyUser = z.object({ name: z.string() }).readonly();

type UserId = z.infer<typeof UserId>;
type ReadonlyUser = z.infer<typeof ReadonlyUser>;

const id = UserId.parse("u_123");
const user = ReadonlyUser.parse({ name: "Ada" });

// user.name = "Grace"; // TypeScript error
console.log(id, user.name);

import { z } from "zod";

const Booking = z.object({
  start: z.coerce.date(),
  end: z.coerce.date(),
}).refine((data) => data.start < data.end, {
  message: "End must be after start",
  path: ["end"],
});

const result = Booking.safeParse({
  start: "2025-01-10",
  end: "2025-01-09",
});

console.log(result.success); // false

