import { z } from "zod";

const Category = z.object({
  name: z.string(),
  get subcategories() {
    return z.array(Category);
  },
});

const category = Category.parse({
  name: "People",
  subcategories: [
    { name: "Politicians", subcategories: [] },
  ],
});

console.log(category.subcategories[0].name);

