import { z } from "zod";

const schema = z.object({
  username: z.string(),
  profile: z.object({ age: z.number() }),
});

const result = schema.safeParse({ username: 42, profile: { age: "old" } });

if (!result.success) {
  const nested = z.treeifyError(result.error);
  const flat = z.flattenError(result.error);
  console.log(nested.properties?.profile?.properties?.age?.errors);
  console.log(flat.fieldErrors);
}

