}

import { z } from "zod";

const username = z.string().refine(async (value) => {
  await Promise.resolve();
  return value.length <= 8;
});

const result = await username.safeParseAsync("billie");

if (result.success) {
  console.log(result.data);
} else {
  console.error(result.error.issues);
}

