import { z } from "zod";

const StringToLength = z.string().transform((value) => value.length);

type Accepted = z.input<typeof StringToLength>; // string
type Produced = z.output<typeof StringToLength>; // number
type Inferred = z.infer<typeof StringToLength>; // number

const length: Produced = StringToLength.parse("hello");
console.log(length);
